async function grep_components(query: string) -> string {
  const grep = require('child_process').exec;
  const command = `grep -r -o -E '(component|class|function|variable)' /ext/core`;
  grep(command, (error, stdout, stderr) => {
    if (error) {
      console.error(`exec error: ${error}`);
      return;
    }
    const components = stdout.trim().split('\n');
    return `Found components: ${components.join(", ")}`;
  });
}

